/* 查询使用从 1 开始的闭区间，a[0]=0 表示前 0 天积分。 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b)  {
    return a < b ? a : b;
}
int mx(int a, int b)  {
    return a > b ? a : b;
}
int read(void)  {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a)  {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x)  {
    printf("%d ", x);
}
void emitstr(int* a, int n)  {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void)  {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int i = 0, l = 0, n = 0, q = 0, r = 0;
    n = read();
    q = read();
    /* 读入时直接累计，a[i] 保存前 i 天之和，不再是某一天原值。 */
    for (i = 1; i < (n + 1); i += 1)  {
        a[i] = (a[(i - 1)] + read());
    }
    for (i = 0; i < q; i += 1)  {
        l = read();
        r = read();
        /* 前 r 天总和减去前 l-1 天总和，保留两端都包含的目标区间。 */
        emit((a[r] - a[(l - 1)]));
    }
    return 0;
}

